namespace fs=std::filesystem;
std::string read(const fs::path& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot read "+p.string());std::ostringstream s;s<<f.rdbuf();return s.str();}
void write(const fs::path& p,const std::string& s){int fd=::open(p.c_str(),O_WRONLY|O_CREAT|O_EXCL,0600);if(fd<0)throw std::runtime_error("exclusive write failed");size_t pos=0;while(pos<s.size()){auto n=::write(fd,s.data()+pos,s.size()-pos);if(n<0&&errno==EINTR)continue;if(n<=0){::close(fd);throw std::runtime_error("write failed");}pos+=size_t(n);}if(::fsync(fd)!=0){::close(fd);throw std::runtime_error("fsync failed");}if(::close(fd)!=0)throw std::runtime_error("close failed");}
void check(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
Batch make_batch(const Json& rows){std::vector<int64_t>x,y;for(const auto&r:rows){for(const auto&v:r.at("input"))x.push_back(v.get<int64_t>());y.push_back(r.at("label").get<int64_t>());}Batch b;b.inputs=torch::from_blob(x.data(),{int64_t(rows.size()),17},torch::kInt64).clone();b.targets=torch::from_blob(y.data(),{int64_t(rows.size())},torch::kInt64).clone();b.mask=b.inputs.ne(0);b.segments=torch::zeros_like(b.inputs);b.target_mask=torch::ones_like(b.targets,torch::kBool);return b;}
torch::Tensor logits(ModelPtr m,const Batch& b){auto z=m->forward(b);auto bad=b.inputs.select(1,0).eq(2).unsqueeze(1)&torch::arange(49,b.inputs.options()).ge(25).unsqueeze(0);return z.masked_fill(bad,-1e9);}
std::string tensor_sha(torch::Tensor t){t=t.detach().contiguous();return sha256(std::string(static_cast<const char*>(t.data_ptr()),t.numel()*t.element_size()));}
Json subset(const Json& rows,size_t start,size_t n){Json p=Json::array();for(size_t i=start;i<std::min(rows.size(),start+n);++i)p.push_back(rows[i]);return p;}
std::string probe(ModelPtr m,const Json& rows){m->eval();torch::NoGradGuard g;return tensor_sha(logits(m,make_batch(subset(rows,0,32))));}
Json evaluate(ModelPtr m,const Json& rows){m->eval();torch::NoGradGuard guard;Json scores=Json::array();for(size_t i=0;i<rows.size();i+=32){auto part=subset(rows,i,32);auto b=make_batch(part);auto z=logits(m,b);auto lp=torch::log_softmax(z,1);auto pred=z.argmax(1);for(size_t j=0;j<part.size();++j)scores.push_back({{"family",part[j].at("family")},{"target_index",part[j].at("target_index")},{"task",part[j].at("task")},{"target",part[j].at("label")},{"prediction",pred[j].item<int64_t>()},{"nll",-lp[j][b.targets[j].item<int64_t>()].item<double>()}});}return scores;}
void validate_rows(const Json& rows){check(rows.is_array()&&!rows.empty(),"empty rows");std::set<std::string> ids;for(const auto&r:rows){auto task=r.at("task").get<std::string>();check(task=="pitch"||task=="rhythm","task");auto x=r.at("input").get<std::vector<int64_t>>();auto y=r.at("label").get<int64_t>();check(x.size()==17&&x[0]==(task=="pitch"?1:2),"task/input");check(y>=0&&y<(task=="pitch"?49:25),"label");for(int i=1;i<17;++i)check(x[i]>=(i%2?3:52)&&x[i]<=(i%2?51:76),"token range/order");check(r.at("target_index").get<int64_t>()>=8,"target index");check(ids.insert(r.at("family").get<std::string>()+":"+r.at("target_index").dump()+":"+task).second,"duplicate identity");}}
std::string optimizer_bytes(torch::optim::AdamW& opt){torch::serialize::OutputArchive a;opt.save(a);std::ostringstream s;a.save_to(s);return s.str();}
void load_optimizer(torch::optim::AdamW& opt,const std::string& bytes){torch::serialize::InputArchive a;std::istringstream s(bytes);a.load_from(s,torch::kCPU);opt.load(a);}
void same_tensor(const torch::Tensor&a,const torch::Tensor&b){check(a.defined()==b.defined(),"tensor defined mismatch");if(a.defined())check(torch::equal(a,b),"tensor reload mismatch");}
void same_model(ModelPtr a,ModelPtr b){auto p=a->named_parameters(),q=b->named_parameters();check(p.size()==q.size(),"parameter count");for(auto& x:p){check(q.contains(x.key()),"parameter key");same_tensor(x.value(),q[x.key()]);}auto u=a->named_buffers(),v=b->named_buffers();check(u.size()==v.size(),"buffer count");for(auto&x:u){check(v.contains(x.key()),"buffer key");same_tensor(x.value(),v[x.key()]);}}
void validate_optimizer_options(torch::optim::AdamW& opt){check(opt.param_groups().size()==1,"optimizer groups");auto&o=dynamic_cast<torch::optim::AdamWOptions&>(opt.param_groups()[0].options());check(o.lr()==0.0003&&o.weight_decay()==0&&o.eps()==1e-8&&o.betas()==std::make_tuple(0.9,0.999)&&!o.amsgrad(),"optimizer options mismatch");}
void same_optimizer(torch::optim::AdamW&a,torch::optim::AdamW&b,ModelPtr ma,ModelPtr mb){validate_optimizer_options(a);validate_optimizer_options(b);auto pa=ma->parameters(),pb=mb->parameters();check(a.state().size()==b.state().size(),"optimizer state count");for(size_t i=0;i<pa.size();++i){auto ka=pa[i].unsafeGetTensorImpl(),kb=pb[i].unsafeGetTensorImpl();check(a.state().count(ka)==b.state().count(kb),"optimizer state presence");if(!a.state().count(ka))continue;auto& x=dynamic_cast<torch::optim::AdamWParamState&>(*a.state().at(ka));auto& y=dynamic_cast<torch::optim::AdamWParamState&>(*b.state().at(kb));check(x.step()==y.step(),"optimizer step");same_tensor(x.exp_avg(),y.exp_avg());same_tensor(x.exp_avg_sq(),y.exp_avg_sq());same_tensor(x.max_exp_avg_sq(),y.max_exp_avg_sq());}}
int main(int argc,char**argv){try{
 check(argc==4||argc==5,"DATA OUTDIR ADDITIONAL_EPOCHS [RESUME_DIR]");fs::path data_path=argv[1],out=argv[2];check(!fs::exists(out),"output exists");int epochs=std::stoi(argv[3]);check(epochs>=1&&epochs<=3,"epoch bound");auto raw=read(data_path);auto d=Json::parse(raw);validate_rows(d.at("train"));validate_rows(d.at("test"));std::set<std::string> trainfamilies;for(auto&r:d.at("train"))trainfamilies.insert(r.at("family"));for(auto&r:d.at("test"))check(!trainfamilies.contains(r.at("family").get<std::string>()),"family leakage");
 ModelConfig c;c.kind="encoder";c.hidden_width=256;c.input_width=2;c.output_width=49;c.vocabulary=77;c.controls={1,2};c.dropout_milli=0;auto m=make_seeded_model(c,42);torch::optim::AdamW opt(m->parameters(),torch::optim::AdamWOptions(0.0003).weight_decay(0));int completed=0;Json resume=nullptr;
 if(argc==5){fs::path src=argv[4];auto manifest=Json::parse(read(src/"manifest.json"));check(manifest.at("schema")=="mousa-offline-music-checkpoint-v1","resume schema");check(manifest.at("complete")==true,"incomplete resume");check(manifest.at("data_sha256")==sha256(raw),"resume data digest");check(manifest.at("model_config")==c.json(),"resume model config");check(manifest.at("optimizer")=="AdamW lr0.0003 wd0 clip1","resume optimizer config");auto weights=read(src/"weights.pt"),states=read(src/"optimizer.pt");check(sha256(weights)==manifest.at("weights_sha256").get<std::string>(),"weights digest");check(sha256(states)==manifest.at("optimizer_sha256").get<std::string>(),"optimizer digest");load_model_bytes(m,weights);load_optimizer(opt,states);validate_optimizer_options(opt);check(probe(m,d.at("train"))==manifest.at("probe_logits_sha256").get<std::string>(),"fresh-process probe mismatch");completed=manifest.at("completed_epochs");check(completed>=1&&completed<=3&&completed<=int(d.at("epochs").size()),"resume completed epoch bound");int64_t prior_steps=0;for(int e=0;e<completed;++e)prior_steps+=d.at("epochs").at(e).size();check(manifest.at("total_steps")==prior_steps,"resume total step manifest");check(opt.state().size()==m->parameters().size(),"resume missing optimizer state");for(auto&p:m->parameters()){auto&st=dynamic_cast<torch::optim::AdamWParamState&>(*opt.state().at(p.unsafeGetTensorImpl()));check(st.step()==prior_steps,"resume optimizer step mismatch");check(torch::isfinite(st.exp_avg()).all().item<bool>()&&torch::isfinite(st.exp_avg_sq()).all().item<bool>(),"resume optimizer nonfinite");}resume={{"manifest_sha256",sha256(read(src/"manifest.json"))},{"fresh_process_probe_exact",true},{"optimizer_steps_restored",prior_steps},{"completed_epochs",completed}};}
 check(completed>=0&&completed+epochs<=int(d.at("epochs").size()),"missing schedules");for(int e=completed;e<completed+epochs;++e){std::set<size_t>seen;for(auto&batch:d.at("epochs")[e]){check(batch.is_array()&&!batch.empty()&&batch.size()<=32,"batch size");for(auto&i:batch){auto index=i.get<size_t>();check(index<d.at("train").size()&&seen.insert(index).second,"schedule duplicate/range");}}check(seen.size()==d.at("train").size(),"incomplete epoch");}
 if(!out.parent_path().empty())fs::create_directories(out.parent_path());check(fs::create_directory(out),"output directory already exists");auto start=std::clock();auto guard=[&](){check(double(std::clock()-start)/CLOCKS_PER_SEC<=180,"CPU budget exceeded");};Json result={{"environment",parse_json(numerical_environment())},{"resume",resume},{"initial_test",evaluate(m,d.at("test"))},{"losses",Json::array()}};auto before=m->parameters()[0].detach().clone();int steps=0;
 for(int e=completed;e<completed+epochs;++e){for(auto&batch:d.at("epochs")[e]){guard();Json rows=Json::array();for(auto&i:batch)rows.push_back(d.at("train")[i.get<size_t>()]);auto b=make_batch(rows);m->train();opt.zero_grad();auto loss=categorical_loss(logits(m,b),b.targets,b.target_mask);check(torch::isfinite(loss).item<bool>(),"nonfinite loss");loss.backward();for(auto&p:m->parameters())check(p.grad().defined()&&torch::isfinite(p.grad()).all().item<bool>(),"invalid gradient");torch::nn::utils::clip_grad_norm_(m->parameters(),1.);opt.step();m->enforce_constraints();result["losses"].push_back(loss.item<double>());++steps;}std::cerr<<"epoch "<<(e+1)<<" done\n";}
 guard();result["final_test"]=evaluate(m,d.at("test"));result["embedding_delta_l1"]=(m->parameters()[0]-before).abs().sum().item<double>();check(result["embedding_delta_l1"].get<double>()>0,"no parameter update");auto weights=save_model_bytes(m),states=optimizer_bytes(opt);auto reloaded=make_seeded_model(c,999);load_model_bytes(reloaded,weights);torch::optim::AdamW ropt(reloaded->parameters(),torch::optim::AdamWOptions(0.0003).weight_decay(0));load_optimizer(ropt,states);same_model(m,reloaded);same_optimizer(opt,ropt,m,reloaded);check(probe(m,d.at("train"))==probe(reloaded,d.at("train")),"reload logits mismatch");result["checkpoint_reload_parameters_exact"]=true;result["checkpoint_reload_optimizer_exact"]=true;result["checkpoint_reload_logits_exact"]=true;result["steps"]=steps;result["cpu_seconds"]=double(std::clock()-start)/CLOCKS_PER_SEC;guard();
 write(out/"weights.pt",weights);write(out/"optimizer.pt",states);write(out/"results.json",result.dump(2)+"\n");int64_t total_steps=0;for(int e=0;e<completed+epochs;++e)total_steps+=d.at("epochs")[e].size();Json manifest={{"total_steps",total_steps},{"schema","mousa-offline-music-checkpoint-v1"},{"complete",true},{"usage","offline research checkpoint, not a validated production bundle"},{"data_sha256",sha256(raw)},{"weights_sha256",sha256(weights)},{"optimizer_sha256",sha256(states)},{"results_sha256",sha256(read(out/"results.json"))},{"model_config",c.json()},{"optimizer","AdamW lr0.0003 wd0 clip1"},{"seed",42},{"completed_epochs",completed+epochs},{"phase_steps",steps},{"probe_logits_sha256",probe(m,d.at("train"))},{"resume",resume},{"environment",parse_json(numerical_environment())}};write(out/"manifest.json",manifest.dump(2)+"\n");std::cout<<manifest.dump(2)<<"\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
